    const rows = bathRows().map(r => ({ c: num(r.bath_salinity), s: frac(r.terminal_survival), r })).filter(x => x.s != null); if (rows.length < 8) return null;
    const band = c => c == null || c <= 0 ? 'No bath' : c <= 10 ? '1-10' : c <= 15 ? '11-15' : c <= 20 ? '16-20' : c <= 25 ? '21-25' : '26+', order = ['No bath', '1-10', '11-15', '16-20', '21-25', '26+'];
    const m = grp(rows, x => band(x.c), x => x.s), ks = order.filter(k => m.has(k)), g = ks.filter(k => m.get(k).length >= 3), kr = g.length > 1 ? T.kruskal(g.map(k => m.get(k))) : { p: null }, sp = T.spearman(rows.filter(x => x.c > 0).map(x => x.c), rows.filter(x => x.c > 0).map(x => x.s));
