    const kr = T.kruskal(ks.map(k => m.get(k))), rank = [...ks].sort((a, b) => med(m.get(b)) - med(m.get(a))), wk = weekly(rows, r => r.s), mk = T.mannKendall(wk.vals.map(med)), all = rows.map(r => r.s), low = rank[rank.length - 1], top = rank[0];
